class Palavra{
    texto : string = ""
    dica : string = ""
}

function indices(p : Palavra, letra : string) : number {
    let resposta : number[] = []
    for (let i : number = 0; i < p.length; i++) {
        if (p.texto[i] === letra) {
            resposta.push(i) // adiciona um elemento ao final do array
        }
    }

    return resposta[]
}

class S37 {
    may : string = "daapo rkk"
    uyu : string = "ooon lcr."
}

function decode(akb48 : S37) : string {
    let t : string = ""

    for (let i : number = 0; i < akb48.may.length; i++) {
            t += akb48.may[akb48.may.length - i - 1]
            t += akb48.uyu[i]
    }

    return t
}

